import{_ as s,c as t,o as n,j as e,a as l}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"離下巽上 家人：","description":"京氏易傳 - 離下巽上 家人：","frontmatter":{"title":"離下巽上 家人：","description":"京氏易傳 - 離下巽上 家人："},"headers":[],"relativePath":"classics/jingshi/044.md","filePath":"classics/jingshi/044.md"}'),i={name:"classics/jingshi/044.md"};function r(c,a,o,p,d,m){return n(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"離下巽上-家人",tabindex:"-1"},[l("離下巽上 家人： "),e("a",{class:"header-anchor",href:"#離下巽上-家人","aria-label":"Permalink to “離下巽上 家人：”"},"​")],-1),e("p",null,"乾剛俱變文明，內外相應，【九五應六二爻。】陰陽得位，居中履正。火上見風，家人之象。閒邪存誠，嗃嗃得中，互體見文明，家道明也。內平遇坎，（虎易注：平字疑為互字之誤。因為家人卦的互卦為未濟卦，其互內卦為坎卦，因此，此處當以“內互遇坎”較為適當。）險象，家人難也。酌中之義，在於六二。與離為飛伏。【己丑土，辛亥水。】",-1),e("p",null,"建始癸卯至戊申，【春分，立秋。】積算起戊申至丁未，金土入離巽。【金土入卦同積算。】大夫居世，應九五立君位。",-1),e("p",null,"五星從位起太陰，【太陰，北方，入卦起宮推算。】箕宿從位降己丑，【二十八宿，分箕宿入家人卦，在己丑土上。】分氣候其數三十六。【三十六起數家人卦，推入積算休咎。】",-1),e("p",null,"火木分形，陰陽得位，內外相資，二氣相和。君君臣臣，父父子子，兄兄弟弟。《易》曰：“家人嗃嗃，父子嘻嘻”。治家之道，分於此也。吉凶之義配五行進退，【六五進退，吉凶於陰陽。陰陽得起，在於四時運動，吉凶見矣，分內外矣。二象配天地星辰，合命定吉凶。】文明運動變化之象。",-1),e("p",null,"九三適陰入震，風為雷，合曰益。次降風雷益卦。",-1)])])}const f=s(i,[["render",r]]);export{_ as __pageData,f as default};
